-- Synthetic v1 sample generated by the unchanged v0.9.0 owner migration callback.
-- Rows are invented fixtures; no deployed database was read.
BEGIN;
CREATE TABLE system_state (
      key TEXT PRIMARY KEY,
      value TEXT,
      updated_at INTEGER
    );
CREATE TABLE task_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id TEXT NOT NULL,
      executed_at INTEGER NOT NULL,
      completed_at INTEGER,
      status TEXT NOT NULL CHECK(status IN ('started', 'success', 'failed', 'timeout')),
      duration_ms INTEGER,
      error TEXT,

      FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
    );
CREATE TABLE tasks (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT,
      prompt TEXT NOT NULL,

      -- Scheduling
      type TEXT NOT NULL CHECK(type IN ('one-time', 'recurring', 'interval')),
      cron_expression TEXT,
      interval_seconds INTEGER,
      timezone TEXT DEFAULT 'UTC',

      -- Timing
      next_run_at INTEGER NOT NULL,
      last_run_at INTEGER,

      -- Priority & Status
      priority INTEGER DEFAULT 3 CHECK(priority BETWEEN 1 AND 3),
      status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'running', 'completed', 'failed', 'paused')),

      -- Execution Control
      require_idle INTEGER DEFAULT 0,           -- 0/1: whether task requires idle state
      miss_threshold INTEGER DEFAULT 300,       -- seconds: skip if overdue by more than this

      -- Reply Configuration
      reply_channel TEXT DEFAULT NULL,          -- reply channel (e.g., 'telegram')
      reply_endpoint TEXT DEFAULT NULL,         -- reply endpoint (e.g., user ID)

      -- Retry Logic (reserved, not currently used)
      -- Implicit retry is handled via miss_threshold: tasks stay pending
      -- until dispatched or overdue beyond miss_threshold window (default 300s).
      -- See daemon.js mainLoop + handleMissedTasks for details.
      retry_count INTEGER DEFAULT 0,
      max_retries INTEGER DEFAULT 3,

      -- Metadata
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,

      -- Error Tracking
      last_error TEXT,
      failed_at INTEGER
    );
CREATE INDEX idx_history_task ON task_history(task_id);
CREATE INDEX idx_history_time ON task_history(executed_at);
CREATE INDEX idx_next_run ON tasks(next_run_at) WHERE status = 'pending';
CREATE INDEX idx_status_priority ON tasks(status, priority);
CREATE INDEX idx_type ON tasks(type);
INSERT INTO "system_state" ("key", "value", "updated_at") VALUES ('fixture-scheduler-v1', 'synthetic scheduler v1 state', 100);
INSERT INTO "tasks" ("id", "name", "description", "prompt", "type", "cron_expression", "interval_seconds", "timezone", "next_run_at", "last_run_at", "priority", "status", "require_idle", "miss_threshold", "reply_channel", "reply_endpoint", "retry_count", "max_retries", "created_at", "updated_at", "last_error", "failed_at") VALUES ('fixture-scheduler-v1', 'synthetic scheduler v1 task', NULL, 'synthetic prompt', 'one-time', NULL, NULL, 'UTC', 100, NULL, 3, 'pending', 0, 300, NULL, NULL, 0, 3, 10, 10, NULL, NULL);
INSERT INTO "task_history" ("id", "task_id", "executed_at", "completed_at", "status", "duration_ms", "error") VALUES (201, 'fixture-scheduler-v1', 100, NULL, 'success', NULL, NULL);
